    offset: int = 0
    while True:
        query = f"SELECT * FROM {table_name} ORDER BY {order_by} LIMIT {batch_size} OFFSET {offset}"
        rows = db.execute_query(query)
        if not rows:
            break
        yield [_row_to_record(row, table_name) for row in rows]
        offset += 1


